<div class="d-flex justify-content-between align-items-center mb-4"><h1>🚚 Proveedores</h1><button class="btn btn-success" data-bs-toggle="modal" data-bs-target="#modalProveedor">➕ Nuevo Proveedor</button></div>
<div class="card"><div class="card-body table-responsive"><table class="table table-hover align-middle"><thead class="table-light"><tr><th>ID</th><th>Razón Social</th><th>Correo</th><th>Teléfono</th><th>Acciones</th></tr></thead><tbody>
<?php foreach ($proveedores as $prov): ?><tr><td><?= (int)$prov['ID_Proveedor'] ?></td><td><?= htmlspecialchars($prov['Razon_Social'],ENT_QUOTES,'UTF-8') ?></td><td><?= htmlspecialchars($prov['Correo']??'-',ENT_QUOTES,'UTF-8') ?></td><td><?= htmlspecialchars($prov['Numero']??'-',ENT_QUOTES,'UTF-8') ?></td><td class="text-nowrap"><button class="btn btn-sm btn-outline-primary btn-editar-proveedor" data-bs-toggle="modal" data-bs-target="#modalEditarProveedor" data-id="<?= (int)$prov['ID_Proveedor'] ?>" data-razon="<?= htmlspecialchars($prov['Razon_Social'],ENT_QUOTES,'UTF-8') ?>" data-correo="<?= htmlspecialchars($prov['Correo']??'',ENT_QUOTES,'UTF-8') ?>" data-numero="<?= htmlspecialchars($prov['Numero']??'',ENT_QUOTES,'UTF-8') ?>"><i class="bi bi-pencil"></i> Actualizar</button><form class="d-inline" method="post" action="index.php?controller=proveedor&action=eliminar" onsubmit="return confirm('¿Eliminar proveedor? No se podrá si tiene ingresos asociados.')"><input type="hidden" name="id" value="<?= (int)$prov['ID_Proveedor'] ?>"><button class="btn btn-sm btn-outline-danger"><i class="bi bi-trash"></i> Eliminar</button></form></td></tr><?php endforeach; ?><?php if (!$proveedores): ?><tr><td colspan="5" class="text-center text-muted">No hay proveedores registrados.</td></tr><?php endif; ?></tbody></table></div></div>
<div class="modal fade" id="modalProveedor" tabindex="-1"><div class="modal-dialog modal-dialog-centered"><form method="POST" action="index.php?controller=proveedor&action=crear" class="modal-content"><div class="modal-header"><h5 class="modal-title">Nuevo Proveedor</h5><button type="button" class="btn-close" data-bs-dismiss="modal"></button></div><div class="modal-body"><div class="mb-3"><label class="form-label">Razón Social</label><input type="text" name="Razon_Social" class="form-control" required maxlength="50"></div><div class="mb-3"><label class="form-label">Correo</label><input type="email" name="Correo" class="form-control" maxlength="50"></div><div class="mb-3"><label class="form-label">Teléfono</label><input type="text" name="Numero" class="form-control" maxlength="20"></div></div><div class="modal-footer"><button type="button" class="btn btn-secondary" data-bs-dismiss="modal">Cancelar</button><button class="btn btn-success">Guardar</button></div></form></div></div>
<div class="modal fade" id="modalEditarProveedor" tabindex="-1"><div class="modal-dialog modal-dialog-centered"><form method="POST" action="index.php?controller=proveedor&action=actualizar" class="modal-content"><div class="modal-header"><h5 class="modal-title">Actualizar proveedor</h5><button type="button" class="btn-close" data-bs-dismiss="modal"></button></div><div class="modal-body"><input type="hidden" name="ID_Proveedor" id="editProvId"><div class="mb-3"><label class="form-label">Razón Social</label><input class="form-control" name="Razon_Social" id="editProvRazon" maxlength="50" required></div><div class="mb-3"><label class="form-label">Correo</label><input class="form-control" type="email" name="Correo" id="editProvCorreo" maxlength="50"></div><div class="mb-3"><label class="form-label">Teléfono</label><input class="form-control" name="Numero" id="editProvNumero" maxlength="20"></div></div><div class="modal-footer"><button type="button" class="btn btn-secondary" data-bs-dismiss="modal">Cancelar</button><button class="btn btn-primary">Guardar cambios</button></div></form></div></div>
<script>document.querySelectorAll('.btn-editar-proveedor').forEach(b=>b.addEventListener('click',function(){document.getElementById('editProvId').value=this.dataset.id;document.getElementById('editProvRazon').value=this.dataset.razon;document.getElementById('editProvCorreo').value=this.dataset.correo;document.getElementById('editProvNumero').value=this.dataset.numero;}));</script>
